:root {
  --bg-card: #f7f2e8;
  --bg-header: #2e1f0e;
  --bg-featured: #4a2f0c;
  --bg-specimen: #ede5d0;
  --bg-chip-preserved: #1e4a2a;
  --bg-chip-labelled: #2a3d6e;
  --bg-chip-pending: #6b3a10;
  --border-main: #8b6840;
  --border-light: #c4a97a;
  --text-primary: #1a0f05;
  --text-secondary: #5c3d1a;
  --text-header: #f0e6cc;
  --text-muted: #9a7a50;
  --text-chip: #f5edda;
  --accent-gold: #c9922a;
  --accent-featured: #e8b84b;
}

.pin-log {
  background: var(--bg-card);
  border: 2px solid var(--border-main);
  border-radius: 4px;
  width: 480px;
  overflow: hidden;
  font-size: 13px;
  color: var(--text-primary);
}

.log-header {
  background: var(--bg-header);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
}

.log-badge {
  background: var(--accent-gold);
  color: var(--bg-header);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
  padding: 4px 7px;
  border-radius: 2px;
  white-space: nowrap;
  flex-shrink: 0;
}

.log-title-block {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.log-title {
  font-size: 15px;
  font-weight: 700;
  color: var(--text-header);
  margin: 0;
  letter-spacing: 0.04em;
  line-height: 1.2;
}

.log-subtitle {
  font-size: 10px;
  color: var(--border-light);
  margin: 0;
  letter-spacing: 0.06em;
}

.log-number {
  font-size: 11px;
  color: var(--border-light);
  letter-spacing: 0.05em;
  text-align: right;
  white-space: nowrap;
  flex-shrink: 0;
}

.log-number span {
  color: var(--accent-gold);
  font-weight: 700;
}

.log-body {
  display: flex;
  gap: 12px;
  padding: 12px 14px;
  border-bottom: 1px solid var(--border-light);
}

.specimen-grid {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex-shrink: 0;
}

.specimen-card {
  background: var(--bg-specimen);
  border: 1px solid var(--border-light);
  border-radius: 4px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 9px;
  margin: 0;
  width: 162px;
}

.specimen-card.featured {
  background: var(--bg-featured);
  border-color: var(--accent-featured);
}

.specimen-card.featured .spec-name {
  color: var(--accent-featured);
}

.specimen-card.featured .spec-label {
  color: var(--border-light);
}

.specimen-icon {
  font-size: 18px;
  line-height: 1;
  flex-shrink: 0;
}

.specimen-card figcaption {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.spec-name {
  font-size: 10px;
  font-weight: 700;
  font-style: italic;
  color: var(--text-secondary);
  line-height: 1.3;
}

.spec-label {
  font-size: 9px;
  color: var(--text-muted);
  letter-spacing: 0.04em;
}

.log-details {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 8px;
}

.detail-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.detail-row {
  display: flex;
  align-items: center;
  gap: 4px;
}

.detail-key {
  font-size: 10px;
  font-weight: 700;
  color: var(--text-muted);
  letter-spacing: 0.04em;
  width: 64px;
  flex-shrink: 0;
}

.detail-dot {
  flex: 1;
  border-bottom: 1px dotted var(--border-light);
  height: 1px;
  margin-bottom: 2px;
}

.detail-val {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-primary);
  text-align: right;
  white-space: nowrap;
}

.status-row {
  display: flex;
  gap: 5px;
  flex-wrap: wrap;
}

.status-chip {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.07em;
  padding: 3px 7px;
  border-radius: 2px;
  color: var(--text-chip);
  text-transform: uppercase;
}

.status-chip.preserved {
  background: var(--bg-chip-preserved);
}

.status-chip.labelled {
  background: var(--bg-chip-labelled);
}

.status-chip.pending {
  background: var(--bg-chip-pending);
}

.log-footer {
  padding: 8px 14px 10px;
}

.footer-rule {
  height: 1px;
  background: var(--border-light);
  margin-bottom: 8px;
}

.footer-cols {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}

.footer-col {
  display: flex;
  flex-direction: column;
  gap: 2px;
  align-items: center;
  border: 1px solid var(--border-light);
  border-radius: 3px;
  padding: 5px 6px;
  background: var(--bg-specimen);
}

.footer-label {
  font-size: 9px;
  font-weight: 700;
  color: var(--text-muted);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.footer-val {
  font-size: 13px;
  font-weight: 700;
  color: var(--accent-gold);
}
